'use client'

import * as React from 'react'

import './flip-card.css'

export type FlipCardProps = {
    front: React.ReactNode
    back: React.ReactNode
    /** Accessible names for the flip button on each side. */
    flipLabel?: { toBack: string, toFront: string }
    flipped?: boolean
    defaultFlipped?: boolean
    onFlippedChange?: (flipped: boolean) => void
    className?: string
}

// The hidden face is inert, so screen readers and Tab only ever reach the side you can see.
// Flipping is an explicit button, never hover-only, so it works for keyboard and touch.
const FlipCard = ({ front, back, flipLabel = { toBack: 'Show back', toFront: 'Show front' }, flipped, defaultFlipped = false, onFlippedChange, className }: FlipCardProps) => {
    const [internal, setInternal] = React.useState(defaultFlipped)
    const isFlipped = flipped ?? internal

    const toggle = () => {
        const next = !isFlipped
        if (flipped === undefined) setInternal(next)
        onFlippedChange?.(next)
    }

    return <div className={['rad-fx-flip', className].filter(Boolean).join(' ')} data-state={isFlipped ? 'back' : 'front'}>
        <div className="rad-fx-flip-inner">
            <div className="rad-fx-flip-face" data-face="front" inert={isFlipped} aria-hidden={isFlipped || undefined}>
                {front}
            </div>
            <div className="rad-fx-flip-face" data-face="back" inert={!isFlipped} aria-hidden={!isFlipped || undefined}>
                {back}
            </div>
        </div>
        {/* The label says what the button will do, so it is not also marked aria-pressed. */}
        <button type="button" className="rad-fx-flip-toggle" onClick={toggle}>
            {isFlipped ? flipLabel.toFront : flipLabel.toBack}
        </button>
    </div>
}

export default FlipCard

.rad-fx-flip {
    position: relative;
    perspective: 1000px;
}

.rad-fx-flip-inner {
    display: grid;
    transform-style: preserve-3d;
    transition: transform 650ms cubic-bezier(0.3, 0.7, 0.2, 1);
}

.rad-fx-flip[data-state='back'] .rad-fx-flip-inner { transform: rotateY(180deg); }

.rad-fx-flip-face {
    grid-area: 1 / 1;
    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;
}

.rad-fx-flip-face[data-face='back'] { transform: rotateY(180deg); }

.rad-fx-flip-toggle {
    position: absolute;
    right: 12px;
    bottom: 12px;
    padding: 4px 10px;
    border: 1px solid currentColor;
    border-radius: 999px;
    background: transparent;
    color: inherit;
    font: inherit;
    font-size: 0.8rem;
    cursor: pointer;
}

.rad-fx-flip-toggle:focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }

/* Reduced motion: a quick cross-fade instead of a 3D turn. */
@media (prefers-reduced-motion: reduce) {
    .rad-fx-flip-inner, .rad-fx-flip[data-state='back'] .rad-fx-flip-inner { transform: none; transition: none; }
    .rad-fx-flip-face, .rad-fx-flip-face[data-face='back'] { transform: none; backface-visibility: visible; transition: opacity 150ms; }
    .rad-fx-flip[data-state='front'] .rad-fx-flip-face[data-face='back'],
    .rad-fx-flip[data-state='back'] .rad-fx-flip-face[data-face='front'] { opacity: 0; }
}

[data-rad-fx-motion='reduce'] .rad-fx-flip-inner,
[data-rad-fx-motion='reduce'] .rad-fx-flip[data-state='back'] .rad-fx-flip-inner { transform: none; transition: none; }
[data-rad-fx-motion='reduce'] .rad-fx-flip-face,
[data-rad-fx-motion='reduce'] .rad-fx-flip-face[data-face='back'] { transform: none; backface-visibility: visible; transition: opacity 150ms; }
[data-rad-fx-motion='reduce'] .rad-fx-flip[data-state='front'] .rad-fx-flip-face[data-face='back'],
[data-rad-fx-motion='reduce'] .rad-fx-flip[data-state='back'] .rad-fx-flip-face[data-face='front'] { opacity: 0; }
